-- Pet battle DATA (pure tables, no game API). Everything about fighting (stats, abilities, effects, families) comes from the RETAIL data in pb_retail.lua (generated from the
-- DB2 tables by pet-battle/gen_retail.py) and the rules in pb_rules.lua. This file only holds OUR choices: which retail kit each creature uses, how its abilities are named,
-- where wild pets appear, and the progression constants.
local D = {}

D.MAX_LEVEL = 25                  -- retail pet levels 1-25 cover the whole world; level 25 = the level 80 cap

-- ZONE PET LEVELS: every zone has its retail wild pet range (lo..hi) and the mob level range of its pet-eligible (wild) species (minMob..maxMob, measured from the
-- spawns, rare outliers left out; frozen here on purpose so pet levels never shift when spawns change). A mob level is spread evenly over the retail range:
-- pet = lo + floor((mob - minMob) * (hi - lo + 1) / (maxMob - minMob + 1)), clamped to lo..hi. Add a zone here together with its id in pb_wild ZONES.
-- Retail ranges: Petopia forum (2012) / WarcraftPets: Elwynn, Dun Morogh, Durotar, Teldrassil, Mulgore, Tirisfal, Eversong, Azuremyst 1-2; Westfall 3-4; Silverpine, Darkshore, Loch Modan, Ghostlands, Bloodmyst 3-5; Redridge 4-5 (DEVNOTES 6.13).
D.zones = {
    [12] = { name = "Elwynn Forest", lo = 1, hi = 2, minMob = 1, maxMob = 10 },
    [1]  = { name = "Dun Morogh",    lo = 1, hi = 2, minMob = 1, maxMob = 10 },
    [14] = { name = "Durotar",       lo = 1, hi = 2, minMob = 1, maxMob = 10 },
    [40] = { name = "Westfall",      lo = 3, hi = 4, minMob = 9, maxMob = 19 },   -- retail Westfall 3-4; the level 1 critters clamp to 3, mobs 9-14 = 3, 15-19 = 4 (first zone with 3-pet fights)
    [141] = { name = "Teldrassil", lo = 1, hi = 2, minMob = 1, maxMob = 11 },
    [215] = { name = "Mulgore", lo = 1, hi = 2, minMob = 1, maxMob = 10 },
    [85] = { name = "Tirisfal Glades", lo = 1, hi = 2, minMob = 1, maxMob = 14 },
    [3430] = { name = "Eversong Woods", lo = 1, hi = 2, minMob = 1, maxMob = 12 },
    [3524] = { name = "Azuremyst Isle", lo = 1, hi = 2, minMob = 1, maxMob = 12 },
    [130] = { name = "Silverpine Forest", lo = 3, hi = 5, minMob = 10, maxMob = 20 },
    [148] = { name = "Darkshore", lo = 3, hi = 5, minMob = 9, maxMob = 21 },
    [38] = { name = "Loch Modan", lo = 3, hi = 5, minMob = 10, maxMob = 20 },
    [44] = { name = "Redridge Mountains", lo = 4, hi = 5, minMob = 8, maxMob = 25 },
    [3433] = { name = "Ghostlands", lo = 3, hi = 5, minMob = 11, maxMob = 20 },
    [3525] = { name = "Bloodmyst Isle", lo = 3, hi = 5, minMob = 9, maxMob = 18 },
}
function D.PetLevel(mobLevel, zoneId)
    local z = zoneId and D.zones[zoneId]
    if not z then return math.max(1, math.min(D.MAX_LEVEL, math.floor((mobLevel or 1) * D.MAX_LEVEL / 80 + 0.5))) end   -- unknown zone: old proportional curve
    local span = z.maxMob - z.minMob + 1
    local lv = z.lo + math.floor(((mobLevel or z.minMob) - z.minMob) * (z.hi - z.lo + 1) / span)
    return math.max(z.lo, math.min(z.hi, lv))
end

-- QUALITY: 1 common (white), 2 uncommon (green), 3 rare (blue), 4 epic (purple). Retail: +10% health/power/speed per step (pb_rules.QualityMult).
D.QUALITY_NAMES = { "Common", "Uncommon", "Rare", "Epic" }
D.QUALITY_WEIGHTS = { 55, 28, 13, 4 }      -- how often a wild pet is each quality
D.CAPTURE_HP = 0.35                        -- retail: an enemy pet can be captured (trap) at or below 35% health; the capture always works, costs your turn, keeps the pet's level/quality/skin
D.REGEN_PCT, D.REGEN_SECONDS = 1, 10       -- a pet recovers 1% of its max health every 10 seconds (also while you are offline)
D.XP_STEP = 0.20                 -- XP: retail table (pb_retail R.xp: wins x XpPerWin per level, a win = XpPerWin of the ENEMY level); our rule on top: -20% per level the enemy is BELOW the pet, 0 at 5+ below

